                    This is a preview of your selected appearance settings. The theme, font size, and compact mode are reflected here.
                </p>
                <div class="d-flex gap-2 @(_compactMode ? "flex-wrap" : "")">
                    <span class="badge bg-primary">Tag</span>
                    <span class="badge bg-secondary">Label</span>
                    <span class="badge bg-success">Status</span>
                </div>
                <hr class="@PreviewTextClass" />
                <small class="@PreviewTextClass" style="@PreviewFontStyle">
                    Language: @_language &bull; Compact: @(_compactMode ? "On" : "Off")
                </small>
            </div>
        </div>
    </div>
}

@code {
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private bool _loading = true;
    private bool _saving;
    private string? _message;
    private bool _isError;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    private string PreviewBackgroundClass => _theme switch
    {
        "Dark" => "bg-dark",
        _ => "bg-light"
    };

    private string PreviewTextClass => _theme switch
    {
        "Dark" => "text-light",
        _ => "text-dark"
    };

    private string PreviewFontStyle => _fontSize switch
    {
        "Small" => "font-size:0.85rem;",
        "Large" => "font-size:1.25rem;",
        _ => "font-size:1rem;"
    };

    private string PreviewStyle => _compactMode
        ? "line-height:1.2;padding:0.75rem !important;"
        : "";

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _message = null;
        try
        {
            var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            _message = "Appearance settings saved!";
            _isError = false;
        }
        catch (Exception ex)
        {
            _message = $"Failed to save settings: {ex.Message}";
            _isError = true;
        }
        finally
        {
            _saving = false;
        }
    }
}
"}

